preConditionHook:
// FAST EMA ABOVE SLOW EMA (Brian's notes ON-39, #39): MA-order state.
// MultiWalk's WFSafe_Xaverage, ported unchanged from EmaGapBar (the EMA
// reference, with the measurements): price seed on the first calculated bar
// (ctx.CurrentBar() == 1), recurrence x + sf*(p - x) in ONE statement,
// sf = 2/(Length+1) from the raw input every bar, state carried on a length
// change (EL_XAverage_Lag_Probe.txt, 2026-09-17).
// Current values only; no history is read.
emaFastSf = 2.0 / (fastLength + 1.0);
emaSlowSf = 2.0 / (slowLength + 1.0);
if (ctx.CurrentBar() == 1) {
    emaFast = close[0];
    emaSlow = close[0];
} else {
    emaFast = emaFast + emaFastSf * (close[0] - emaFast);
    emaSlow = emaSlow + emaSlowSf * (close[0] - emaSlow);
}
